(()=>{
const moduleBase=setModule,entryBase=enterWorkspace,newBase=openNewConversation;
let preparedActivityRole=null;
openActivityBoard=function(){if(preparedActivityRole!==chosenRole.id){moduleBase('业务概览');preparedActivityRole=chosenRole.id}else{['market-view','automation-view','record-view','myspace-view','task-view'].forEach(id=>document.getElementById(id)?.setAttribute('hidden',''));document.getElementById('myspace-nav')?.classList.remove('active');document.getElementById('automation-nav')?.classList.remove('active')}document.querySelector('main').hidden=false;document.getElementById('settings-view')?.setAttribute('hidden','');document.querySelector('.assistant-panel').hidden=true;document.querySelector('main .demo').hidden=true;document.getElementById('stats').hidden=false;if(isOpsRole()||sessionStorage.getItem('yunxu-role')==='purchase-admin')document.getElementById('concerns').hidden=true;document.getElementById('title').textContent=chosenRole.welcome;document.getElementById('title').textContent='早晨好，'+chosenRole.person+'。这里是今天的业务概况。';document.getElementById('subtitle').textContent=isOpsRole()?'ERP库存服务运行概况：关注接口延迟、同步异常、告警处置与变更验证。所有指标为示例。':chosenRole.sub;let v=document.getElementById('activity-view');if(!v){v=document.createElement('section');v.id='activity-view';v.className='activity-view';const f=document.createElement('iframe');initializeActivityFrame(f);f.title='工作动态';v.append(f)}v.classList.add('merged-activity');if(v.parentElement!==document.querySelector('main'))document.querySelector('main').append(v);v.hidden=false;document.getElementById('crumb').textContent='工作动态';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.name==='工作动态'));window.scrollTo(0,0)};
enterWorkspace=function(){entryBase();preparedActivityRole=chosenRole.id;openNewConversation()};
openNewConversation=function(){newBase();document.getElementById('activity-view')?.setAttribute('hidden','');document.querySelector('main .demo').hidden=false};
window.addEventListener('message',e=>{const f=document.querySelector('#activity-view iframe');if(e.origin!==location.origin||e.source!==f?.contentWindow||e.data?.type!=='erp-activity-height')return;const h=Number(e.data.height);if(Number.isFinite(h)&&h>0){const next=Math.min(20000,Math.max(420,Math.ceil(h)))+'px';if(f.style.height!==next)f.style.height=next}});
document.querySelector('#nav [data-name="业务概览"]')?.remove();
})();
